59	    @Column(name = "grade", nullable = false)
60	    private Map<LocalDate, String> datedGrades = new TreeMap<>();
61	
62	    /** Each grade recorded after the first, oldest first, with the sheet's today it was recorded on. */
63	    @ElementCollection(fetch = FetchType.EAGER)
64	    @CollectionTable(name = "person_grade_log", joinColumns = @JoinColumn(name = "person_id"))
65	    @OrderColumn(name = "seq")
66	    private List<PersonGradeLine> gradeLog = new ArrayList<>();
67	
68	    /** The sheet's today when they were added; null when added before this was kept. */
69	    @Column(name = "added_on", updatable = false)
70	    private LocalDate addedOn;
71	
72	    /** The sheet's today when their retirement date was last set; null while not retired, or set before this was kept. */
