196	    public boolean heldOn(LocalDate date) { return holds.stream().anyMatch(h -> h.contains(date)); }
197	
198	    /**
199	     * Whether the date falls within any of their holds put on while the sheet's today was on or before the
200	     * as-of date.
201	     */
202	    public boolean heldOn(LocalDate date, LocalDate asOf) {
203	        return holds.stream().anyMatch(h -> h.putOnBy(asOf) && h.contains(date));
204	    }
205	
206	    /** Whether, as it stood at the end of the date, they were retired by it: retired then, from on or before it. */
207	    public boolean retiredAt(LocalDate date) {
208	        return retiredOn(date) && (retiredOn == null || !retiredOn.isAfter(date));
209	    }
210	
211	    /** Whether their retirement date is reached on the date (the date on or after it). */
212	    public boolean retiredOn(LocalDate date) { return retiredFrom != null && date != null && !date.isBefore(retiredFrom); }
213	
214	    /** Whether an open claim of theirs is kept out of the live totals: dated within a hold, or retired by the sheet's today. */
215	    private boolean keptOut(Claim claim, LocalDate today) { return heldOn(claim.getDate()) || retiredOn(today); }
216	
217	    /**
218	     * Whether a claim of theirs counts in the live totals: it counts by its status, unless it is open
219	     * (OPEN or PENDING), dated within a hold or theirs once their retirement date is reached on the
220	     * sheet's today, and not bound by a statement, or deferred on the sheet's today.
221	     */
222	    public boolean counts(Claim claim, LocalDate today) {
223	        if (!claim.getStatus().counts() || claim.isDeferredOn(today)) return false;
224	        return !claim.getStatus().isOpen() || claim.isBound() || !keptOut(claim, today);
225	    }
226	
227	    /**
228	     * Whether a claim of theirs counts for a period ending on the date: by the status it had at the end
229	     * of that date, less a deferred one and one still open now (OPEN or PENDING) dated within a hold, or
230	     * theirs once retired on the sheet's today, and not bound, as the live rules say: a claim since settled or voided is no longer kept out by a hold.
231	     */
232	    public boolean countsAt(Claim claim, LocalDate end, LocalDate today) {
233	        ClaimStatus at = claim.statusAt(end);
234	        if (at == null || !at.counts() || claim.isDeferredOn(today)) return false;
235	        return !claim.getStatus().isOpen() || claim.isBound() || !keptOut(claim, today);
236	    }
237	
238	    /**
239	     * Whether they are active on the date: they have an open claim (OPEN or PENDING) that counts, dated
240	     * within the 30 days up to and including it.
241	     */
242	    public boolean activeOn(Iterable<Claim> claims, LocalDate today) {
243	        if (today == null) return false;
244	        LocalDate since = today.minusDays(29);
245	        for (Claim claim : claims) {
246	            if (!getId().equals(claim.getPersonId()) || !claim.getStatus().isOpen() || !counts(claim, today)) continue;
247	            if (!claim.getDate().isBefore(since) && !claim.getDate().isAfter(today)) return true;
248	        }
249	        return false;
250	    }
251	
252	    /** Moved on by each save; an edit is refused unless made from the current version. */
253	    public long getVersion() { return version; }
254	}
