7	import java.util.List;
8	import java.util.Map;
9	import java.util.Objects;
10	import java.util.Set;
11	import java.util.stream.Collectors;
12	import net.officefloor.hq.app.Audit;
13	import net.officefloor.hq.app.claim.Claim;
14	import net.officefloor.hq.app.claim.ClaimRepository;
15	import net.officefloor.hq.app.rollup.RollupService;
16	import net.officefloor.hq.app.setting.Role;
17	import net.officefloor.hq.app.setting.SettingService;
18	import net.officefloor.hq.app.sheet.Sheet;
19	import net.officefloor.hq.app.sheet.SheetNotFoundException;
20	import net.officefloor.hq.app.sheet.SheetRepository;
21	import org.springframework.dao.DataIntegrityViolationException;
22	import org.springframework.orm.ObjectOptimisticLockingFailureException;
23	import org.springframework.stereotype.Service;
24	import org.springframework.transaction.annotation.Transactional;
25	
26	/**
27	 * The people on a sheet: listed in the order they were added, added and edited one at a time. A
28	 * name already used by another person on the sheet (ignoring case and surrounding spaces) is
29	 * refused, and so is an edit made from a version of the person someone else has saved since. A
30	 * person can be retired from a date (blank: the sheet's today), and put on hold from a from-date (blank: the sheet's today) to an optional to-date, any number of
31	 * times. A
32	 * person can name other people on the sheet as their patrons, one at a time; not themselves, and
33	 * not the same person twice. A person's grade is dated: the first one given is in force from the
34	 * beginning of time, and each edit records the grade from its from-date (blank: the sheet's today),
35	 * unless it leaves the grade as in force on the sheet's today with the from-date blank. A person may
36	 * have their own terms in days (null: none), given on the add and on each edit, and a contact (blank:
37	 * none), kept without surrounding spaces and lower-cased; one another person on the sheet has is refused.
38	 */
39	@Service
40	public class PersonService {
41	
42	    private final PersonRepository people;
43	    private final PersonPatronRepository patrons;
44	    private final PersonWatchRepository watches;
45	    private final SheetRepository sheets;
46	    private final ClaimRepository claims;
47	    private final RollupService rollup;
48	    private final SettingService settings;
49	    private final Audit audit;
50	
51	    public PersonService(PersonRepository people, PersonPatronRepository patrons,
52	            PersonWatchRepository watches, SheetRepository sheets, ClaimRepository claims, RollupService rollup,
53	            SettingService settings, Audit audit) {
54	        this.claims = claims;
55	        this.watches = watches;
56	        this.people = people;
57	        this.patrons = patrons;
58	        this.sheets = sheets;
59	        this.rollup = rollup;
60	        this.settings = settings;
61	        this.audit = audit;
62	    }
63	
64	    @Transactional(readOnly = true)
65	    public List<Person> list(String sheetId) {
66	        return people.findBySheetIdOrderByIdAsc(sheetId);
67	    }
68	
69	    /** The ids of the sheet's people who are active on its today ({@link Person#activeOn}). */
70	    @Transactional(readOnly = true)
71	    public Set<Long> activeIds(String sheetId) {
72	        LocalDate today = today(sheetId);
73	        List<Claim> all = claims.findBySheetIdOrderByIdDesc(sheetId);
74	        Set<Long> ids = new HashSet<>();
75	        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
76	            if (person.activeOn(all, today)) ids.add(person.getId());
77	        }
78	        return ids;
79	    }
80	
81	    /** Whether the person is active on their sheet's today. */
82	    @Transactional(readOnly = true)
83	    public boolean isActive(Person person) {
84	        return person.activeOn(claims.findBySheetIdAndPersonIdOrderByIdDesc(person.getSheetId(), person.getId()),
85	                today(person.getSheetId()));
86	    }
87	
88	    /** The sheet's today, or null when there is no such sheet. */
89	    @Transactional(readOnly = true)
90	    public LocalDate today(String sheetId) {
91	        return sheets.findById(sheetId).map(Sheet::getToday).orElse(null);
92	    }
93	
94	    @Transactional
95	    public Person add(String sheetId, String user, String name, String grade) {
96	        return add(sheetId, user, name, grade, null, null);
97	    }
98	
99	    /** Add a person with their own terms in days (null: none) and contact (blank: none). */
100	    @Transactional
101	    public Person add(String sheetId, String user, String name, String grade, Integer terms, String contact) {
102	        if (!sheets.existsById(sheetId)) throw new SheetNotFoundException();
103	        requireUnused(sheetId, name, null);
104	        String key = Person.contactOf(contact);
105	        requireContactUnused(sheetId, key, null);
106	        RollupService.Snapshot before = rollup.snapshot(sheetId);
107	        Person draft = new Person(sheetId, name, grade, today(sheetId));
108	        draft.setTerms(terms);
109	        draft.setContact(key);
110	        Person person = saveUnique(draft);
111	        record("PERSON_ADDED", sheetId, user, person, person.getGrade(),
112	                (terms != null ? " terms=" + terms : "") + (key != null ? " contact=" + key : ""));
113	        rollup.recordChanges(sheetId, user, before);
114	        return person;
115	    }
116	
117	    @Transactional
118	    public Person edit(String sheetId, String user, Long id, long version, String name, String grade,
119	            LocalDate gradeFrom, Integer terms, String contact) {
120	        Person person = people.findByIdAndSheetId(id, sheetId).orElseThrow(PersonNotFoundException::new);
121	        if (person.getVersion() != version) throw new PersonVersionConflictException();
122	        requireUnused(sheetId, name, id);
123	        String key = Person.contactOf(contact);
124	        requireContactUnused(sheetId, key, id);
125	        RollupService.Snapshot before = rollup.snapshot(sheetId);
126	        LocalDate today = today(sheetId);
127	        person.setName(name);
128	        boolean termsChanged = !Objects.equals(terms, person.getTerms());
129	        person.setTerms(terms);
130	        boolean contactChanged = !Objects.equals(key, person.getContact());
131	        person.setContact(key);
132	        if (gradeFrom != null || !grade.equals(person.gradeOn(today))) {
133	            person.setGradeFrom(gradeFrom != null ? gradeFrom : today, grade, today);
134	        }
135	        Person saved = saveUnique(person);
136	        record("PERSON_EDITED", sheetId, user, saved, saved.gradeOn(today),
137	                (termsChanged ? " terms=" + (terms != null ? terms : "") : "")
138	                        + (contactChanged ? " contact=" + (key != null ? key : "") : ""));
139	        rollup.recordChanges(sheetId, user, before);
140	        return saved;
141	    }
142	
143	    /**
144	     * Give each of the people the grade from the date (blank: the sheet's today), in list order, each as
145	     * its own edit would: name and terms kept, with its PERSON_EDITED and rollup lines, and no grade
146	     * recorded for one left on the grade in force today with the date blank. One not on the
147	     * sheet refuses them all. A viewer's, or one on an archived sheet, goes through with nothing done.
148	     * Returns how many were changed.
149	     */
150	    @Transactional
151	    public int bulkGrade(String sheetId, String user, Set<Long> ids, String grade, LocalDate from) {
152	        Sheet sheet = sheets.findById(sheetId).orElseThrow(SheetNotFoundException::new);
153	        if (sheet.isArchived() || settings.roleOf(sheetId, user) == Role.VIEWER) return 0;
154	        LocalDate today = sheet.getToday();
155	        List<Person> chosen = people.findBySheetIdOrderByIdAsc(sheetId).stream()
156	                .filter(p -> ids.contains(p.getId())).toList();
157	        if (chosen.size() != ids.size()) throw new PersonNotFoundException();
158	        LocalDate on = from != null ? from : today;
159	        for (Person person : chosen) {
160	            RollupService.Snapshot before = rollup.snapshot(sheetId);
161	            if (from != null || !grade.equals(person.gradeOn(today))) person.setGradeFrom(on, grade, today);
162	            Person saved = saveUnique(person);
163	            record("PERSON_EDITED", sheetId, user, saved, saved.gradeOn(today), "");
164	            rollup.recordChanges(sheetId, user, before);
165	        }
166	        return chosen.size();
167	    }
168	
169	    @Transactional
170	    public Person retire(String sheetId, String user, Long id, LocalDate from) {
171	        // Lock the sheet so no claim is added or edited for them meanwhile against the old date.
172	        LocalDate today = sheets.findForUpdate(sheetId).orElseThrow(SheetNotFoundException::new).getToday();
173	        Person person = people.findByIdAndSheetId(id, sheetId).orElseThrow(PersonNotFoundException::new);
174	        // Once the sheet's today reaches the date, their open claims leave the totals.
175	        RollupService.Snapshot before = rollup.snapshot(sheetId);
176	        LocalDate on = from != null ? from : today;
177	        person.retireFrom(on, today);
178	        Person saved = saveUnique(person);
179	        audit.recordOnCommit("PERSON_RETIRED sheet=" + sheetId + " by=" + user.strip()
180	                + " name=" + saved.getName() + " from=" + on);
181	        rollup.recordChanges(sheetId, user, before);
182	        return saved;
183	    }
184	
185	    /**
186	     * Put the person on hold from the date (blank: the sheet's today) to the optional to-date; their
187	     * open (OPEN or PENDING) claims dated within it, unless bound by a statement, leave the totals.
188	     */
189	    @Transactional
190	    public Person hold(String sheetId, String user, Long id, LocalDate from, LocalDate to) {
191	        RollupService.Snapshot before = rollup.snapshot(sheetId);
192	        Person person = people.findByIdAndSheetId(id, sheetId).orElseThrow(PersonNotFoundException::new);
193	        LocalDate on = from != null ? from : today(sheetId);
194	        if (on == null) throw new SheetNotFoundException();
195	        if (to != null && to.isBefore(on)) throw new HoldDatesException();
196	        person.addHold(new PersonHold(on, to, today(sheetId)));
197	        Person saved = saveUnique(person);
198	        audit.recordOnCommit("PERSON_HELD sheet=" + sheetId + " by=" + user.strip()
199	                + " name=" + saved.getName() + " from=" + on);
200	        rollup.recordChanges(sheetId, user, before);
201	        return saved;
202	    }
203	
204	    /** Each person's patrons' ids on the sheet, by person id, in the order they were named. */
205	    @Transactional(readOnly = true)
206	    public Map<Long, List<Long>> patronIds(String sheetId) {
207	        Map<Long, List<Long>> by = new HashMap<>();
208	        for (PersonPatron p : patrons.findBySheetIdOrderByIdAsc(sheetId)) {
209	            by.computeIfAbsent(p.getPersonId(), k -> new ArrayList<>()).add(p.getPatronId());
210	        }
211	        return by;
212	    }
213	
214	    /** The person's patrons' ids, in the order they were named. */
215	    @Transactional(readOnly = true)
216	    public List<Long> patronIdsOf(Long personId) {
217	        return patrons.findByPersonIdOrderByIdAsc(personId).stream().map(PersonPatron::getPatronId).toList();
218	    }
219	
220	    /** Name another person on the sheet as the person's patron; not themselves, nor one already named. */
221	    @Transactional
222	    public Person addPatron(String sheetId, String user, Long id, Long patronId) {
223	        Person person = people.findByIdAndSheetId(id, sheetId).orElseThrow(PersonNotFoundException::new);
224	        Person patron = people.findByIdAndSheetId(patronId, sheetId).orElseThrow(PersonNotFoundException::new);
225	        if (person.getId().equals(patron.getId())) throw new PatronRefusedException();
226	        if (patrons.existsByPersonIdAndPatronId(person.getId(), patron.getId())) throw new PatronRefusedException();
227	        try {
228	            patrons.saveAndFlush(new PersonPatron(sheetId, person.getId(), patron.getId()));
229	        } catch (DataIntegrityViolationException e) {
230	            // named by another user meanwhile
231	            throw new PatronRefusedException();
232	        }
233	        audit.recordOnCommit("PATRON_ADDED sheet=" + sheetId + " by=" + user.strip()
234	                + " name=" + person.getName() + " patron=" + patron.getName());
235	        return person;
236	    }
237	
238	    /** The ids of the people on the sheet the user watches. */
239	    @Transactional(readOnly = true)
240	    public Set<Long> watchedIds(String sheetId, String user) {
241	        return watches.findBySheetIdAndUserName(sheetId, user.strip()).stream()
242	                .map(PersonWatch::getPersonId).collect(Collectors.toSet());
243	    }
244	
245	    /** Whether the user watches the person. */
246	    @Transactional(readOnly = true)
247	    public boolean watches(Long personId, String user) {
248	        return watches.findByPersonIdAndUserName(personId, user.strip()).isPresent();
249	    }
250	
251	    /** The users watching the person, in the order they started watching. */
252	    @Transactional(readOnly = true)
253	    public List<String> watchersOf(Long personId) {
254	        return watches.findByPersonIdOrderByIdAsc(personId).stream().map(PersonWatch::getUserName).toList();
255	    }
256	
257	    /** Start (true) or stop (false) watching the person as the user; already so, nothing changes. */
258	    @Transactional
259	    public Person watch(String sheetId, String user, Long id, boolean on) {
260	        Person person = people.findByIdAndSheetId(id, sheetId).orElseThrow(PersonNotFoundException::new);
261	        String name = user.strip();
262	        var existing = watches.findByPersonIdAndUserName(person.getId(), name);
263	        if (on == existing.isPresent()) return person;
264	        if (on) {
265	            try {
266	                watches.saveAndFlush(new PersonWatch(sheetId, person.getId(), name));
267	            } catch (DataIntegrityViolationException e) {
268	                // started meanwhile in another window
269	                return person;
270	            }
271	        } else {
272	            watches.delete(existing.get());
273	            watches.flush();
274	        }
275	        audit.recordOnCommit((on ? "PERSON_WATCHED" : "PERSON_UNWATCHED") + " sheet=" + sheetId + " by=" + name
276	                + " name=" + person.getName());
277	        return person;
278	    }
279	
280	    private void record(String event, String sheetId, String user, Person person, String grade, String tail) {
281	        audit.recordOnCommit(event + " sheet=" + sheetId + " by=" + user.strip()
282	                + " name=" + person.getName() + " grade=" + grade + tail);
283	    }
284	
285	    private void requireUnused(String sheetId, String name, Long self) {
286	        people.findBySheetIdAndNameKey(sheetId, Person.keyOf(name))
287	                .filter(other -> !other.getId().equals(self))
288	                .ifPresent(other -> { throw new DuplicatePersonNameException(); });
289	    }
290	
291	    private void requireContactUnused(String sheetId, String contact, Long self) {
292	        if (contact == null) return;
293	        people.findBySheetIdAndContact(sheetId, contact)
294	                .filter(other -> !other.getId().equals(self))
295	                .ifPresent(other -> { throw new DuplicatePersonContactException(); });
296	    }
297	
298	    /** Writes the person now, so a name taken meanwhile by another user is refused by the store. */
299	    private Person saveUnique(Person person) {
300	        try {
301	            return people.saveAndFlush(person);
302	        } catch (DataIntegrityViolationException e) {
303	            throw new DuplicatePersonNameException();
304	        } catch (ObjectOptimisticLockingFailureException e) {
305	            throw new PersonVersionConflictException();
306	        }
307	    }
308	}
