    if (!/^\d{1,12}(\.\d{1,2})?$/.test(amount)) {
      this.quickError.set('Enter an amount of 0.00 or more, with at most two decimals.');
      return;
    }
    this.quickAdding = true;
    try {
      const done = await firstValueFrom(
